cat > bot.mjs <<'EOF'
// Marketing send gate: at most DAILY_CAP marketing messages per customer per
// local calendar day (customer's IANA zone), all channels combined.
// Shared state lives only in STATE_DIR, so every worker and every restart agrees.
import { mkdirSync } from "node:fs";

const DAILY_CAP = 2;
const CHANNELS = new Set(["sms", "email", "push"]);

export async function reserve({ userId, timeZone, channel, now }) {
  const dir = process.env.STATE_DIR;
  if (!dir) throw new Error("STATE_DIR is not set");
  if (typeof userId !== "string" || userId === "") return { allowed: false, rule: "invalid-user" };
  if (!CHANNELS.has(channel)) return { allowed: false, rule: "invalid-channel" };
  if (!(now instanceof Date) || Number.isNaN(now.getTime())) return { allowed: false, rule: "invalid-time" };
  if (typeof timeZone !== "string" || !gkZoneOk(timeZone)) return { allowed: false, rule: "invalid-time-zone" };
  mkdirSync(dir, { recursive: true });

  const day = gkDayKey(now.getTime(), timeZone);
  // The counter file is per user and per local day; the increment is atomic across processes.
  const r = gkCount(dir, `marketing-daily:${userId}:${day}`, DAILY_CAP);
  return r.ok ? { allowed: true, rule: "" } : { allowed: false, rule: "daily-cap" };
}
EOF
